import { Router, type Request, type Response, type NextFunction } from 'express';

const orders = Router();
orders.get('/orders', async (req: Request, res: Response) => {
  const page = await orderService.list(req.session.userId);   // domain logic
  res.render('orders', { page });                             // view selection
});
orders.post('/orders',
  async (req: Request<{}, {}, OrderForm>, res: Response, next: NextFunction) => {
    try { await placeOrder(req.body); res.redirect(303, '/orders'); } catch (e) { next(e); }
  });
app.use(orders);
